class Solution {
    long long totalSum = 0;
    long long maxProd = 0;
    static const int MOD = 1000000007;

    long long computeSum(TreeNode* node) {
        if (!node) return 0;
        return (long long)node->val + computeSum(node->left) + computeSum(node->right);
    }

    long long dfs(TreeNode* node) {
        if (!node) return 0;
        long long left = dfs(node->left);
        long long right = dfs(node->right);
        long long subtreeSum = (long long)node->val + left + right;
        long long product = subtreeSum * (totalSum - subtreeSum);
        if (product > maxProd) maxProd = product;
        return subtreeSum;
    }

public:
    int maxProduct(TreeNode* root) {
        totalSum = 0;
        maxProd = 0;
        totalSum = computeSum(root);
        dfs(root);
        return (int)(maxProd % MOD);
    }
};
